llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C36"],
      "claim": "Omadacycline, a polar polycyclic antibiotic, has an absolute oral bioavailability of 34.5% in healthy adults, directly demonstrating that a highly functionalized, polar natural-product-like molecule can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "CGP 43371, a complex macrolide, had only 9% oral bioavailability, with the low value attributed to poor aqueous solubility (<1 µg/mL); this is the main contradictory low-F anchor.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C51"],
      "claim": "Hydrocortisone, a rigid polycyclic corticosteroid, showed absolute oral bioavailability of 93% (95% CI 0.83-1.05) in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "9-Aminocamptothecin, a pentacyclic lactone, showed oral bioavailability of about 49% in patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Dihydroartemisinin, a polycyclic lactone natural product, showed oral bioavailability >80% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Ixabepilone, a complex macrocyclic lactone, showed oral bioavailability of 43% in patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Etoposide, a polycyclic lactone glycoside, showed mean absolute oral bioavailability around 50% in patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C64"],
      "claim": "Erythromycin, a macrolide, has oral bioavailability approximately 25% in humans, still above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Idarubicin, a polar anthracycline, showed mean oral bioavailability of 29.1% in patients, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of transferable experimental evidence, including the highest-transfer analogue omadacycline (F=34.5%) and numerous polycyclic lactone/macrolide natural products with F=25-85%, supports oral bioavailability ≥20%. The only clear low-F analogue is solubility-limited, a liability not shared by the query, so the physicochemical prior is overridden.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule; prediction relies on transferable analogues.",
    "The query's very low logD and high HBA count may be more extreme than some supportive analogues, so permeability-limited absorption cannot be fully excluded.",
    "The low-F analogue CGP 43371 is explicitly solubility-limited; its relevance to the query's solubility-favorable profile is uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

